export interface CustomInputHandle {
  focus(): void;
  clear(): void;
  selectAll(): void;
}

import { forwardRef, useImperativeHandle, useRef, useState } from 'react';
import { CustomInputHandle } from './types';

export const CustomInput = forwardRef<CustomInputHandle, object>((props, ref) => {
  const inputRef = useRef<HTMLInputElement>(null);
  const [value, setValue] = useState('');

  useImperativeHandle(ref, () => ({
    focus: () => inputRef.current?.focus(),
    clear: () => setValue(''),
    selectAll: () => {
      inputRef.current?.focus();
      inputRef.current?.select();
    },
  }));

  return (
    <input
      ref={inputRef}
      value={value}
      onChange={e => setValue(e.target.value)}
      placeholder="Custom input"
    />
  );
});

CustomInput.displayName = 'CustomInput';

import { useRef } from 'react';
import { CustomInputHandle } from './types';
import { CustomInput } from './CustomInput';

export function SearchBar() {
  const ref = useRef<CustomInputHandle>(null);

  return (
    <div>
      <CustomInput ref={ref} />
      <button onClick={() => ref.current?.focus()}>Focus</button>
      <button onClick={() => ref.current?.clear()}>Clear</button>
      <button onClick={() => ref.current?.selectAll()}>Select All</button>
    </div>
  );
}

import { useRef, useState, useEffect } from 'react';

export function MeasuredBox() {
  const ref = useRef<HTMLDivElement>(null);
  const [size, setSize] = useState({ width: 0, height: 0 });

  useEffect(() => {
    if (ref.current) {
      const { width, height } = ref.current.getBoundingClientRect();
      setSize({ width: Math.round(width), height: Math.round(height) });
    }
  }, []);

  return (
    <div>
      <div ref={ref} style={{ padding: 20, border: '1px solid black' }}>
        Measure me
      </div>
      <p>Width: {size.width}, Height: {size.height}</p>
    </div>
  );
}

import { useRef, useState } from 'react';

export function FocusGroup() {
  const refs = useRef<(HTMLInputElement | null)[]>([]);
  const [current, setCurrent] = useState(0);
  const count = 3;

  function focusNext() {
    const next = (current + 1) % count;
    refs.current[next]?.focus();
    setCurrent(next);
  }

  return (
    <div>
      {Array.from({ length: count }, (_, i) => (
        <input
          key={i}
          ref={el => (refs.current[i] = el)}
          placeholder={`Input ${i + 1}`}
        />
      ))}
      <button onClick={focusNext}>Focus Next</button>
    </div>
  );
}

import { SearchBar } from './SearchBar';
import { MeasuredBox } from './MeasuredBox';
import { FocusGroup } from './FocusGroup';

export function App() {
  return (
    <div>
      <SearchBar />
      <MeasuredBox />
      <FocusGroup />
    </div>
  );
}
